script.source:
const flag = "skirmisherBonus";
return {
  move: {
    hook: "onMove", ownerMoveOnly: true,
    async run(H, actor, ctx) {
      const stat = H.zone.isClose(ctx.toZone) ? "quick" : H.zone.isRanged(ctx.toZone) ? "sharp" : "";
      if (!stat) return;
      const bonus = actor.getFlag("hollows", flag) || {};
      if (bonus[stat]) return;
      await actor.setFlag("hollows", flag, { ...bonus, [stat]: 2 });
      await H.chat.post(actor.name + " gains +2 " + stat + " until their next turn (Skirmisher).", actor);
    },
  },
  bonus: {
    hook: "statModifier",
    run: (H, actor, ctx) => actor.getFlag("hollows", flag)?.[ctx.stat] || 0,
  },
  clear: {
    hook: "startOfTurn", stage: "cleanup",
    run: (H, actor) => actor.unsetFlag("hollows", flag),
  },
  combat: {
    hook: "interceptor", event: "combat-start-hunter",
    run: (H, actor) => actor.unsetFlag("hollows", flag),
  },
};
